<template><div><div class="d-flex flex-column flex-sm-row justify-space-between align-sm-center mb-6"><div><h1 class="text-h4 font-weight-bold mb-2">Pemesanan Saya</h1><p class="grey--text mb-0">Pantau permintaan dan penawaran perjalanan Anda.</p></div><v-btn color="primary" large class="mt-4 mt-sm-0" to="/customer/pesan"><v-icon left>mdi-plus</v-icon>Pesan Bus</v-btn></div><v-card v-if="bookings.length" flat class="booking-list"><v-list three-line><template v-for="(booking,i) in bookings"><v-list-item :key="booking.id" class="pa-4"><v-list-item-avatar tile size="58" color="deep-purple lighten-5" class="rounded-lg"><v-icon color="primary">mdi-bus</v-icon></v-list-item-avatar><v-list-item-content><div class="d-flex flex-wrap align-center mb-1"><v-list-item-title class="font-weight-bold mr-3">{{ booking.origin }} — {{ booking.destination }}</v-list-item-title><v-chip small color="orange lighten-5" text-color="orange darken-3">{{ booking.status }}</v-chip></div><v-list-item-subtitle><v-icon x-small>mdi-calendar</v-icon> {{ formatDate(booking.departureDate) }} &nbsp; • &nbsp; {{ busName(booking.busType) }} &nbsp; • &nbsp; {{ booking.passengers }} peserta</v-list-item-subtitle><div class="caption grey--text mt-1">No. {{ booking.id }}</div></v-list-item-content></v-list-item><v-divider v-if="i<bookings.length-1" :key="`${booking.id}-divider`" /></template></v-list></v-card><v-card v-else flat class="empty pa-10 text-center"><div class="empty-icon mx-auto mb-5"><v-icon size="58" color="primary">mdi-clipboard-text-outline</v-icon></div><h2 class="text-h6 font-weight-bold">Belum ada pemesanan</h2><p class="grey--text">Mulai rencanakan perjalanan pertama Anda bersama EZBus.</p><v-btn color="primary" to="/customer/pesan">Pesan Bus Sekarang</v-btn></v-card></div></template>
<script>export default{data:()=>({bookings:[]}),created(){try{this.bookings=JSON.parse(localStorage.getItem('customerBookings')||'[]')}catch(_){this.bookings=[]}},methods:{formatDate(date){return new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'long',year:'numeric'}).format(new Date(`${date}T00:00:00`))},busName(type){return({medium:'Medium Bus',large:'Large Bus',luxury:'Luxury Bus'})[type]||type}}}</script>
<style scoped>.booking-list,.empty{border-radius:18px!important;border:1px solid #ececf3}.empty-icon{width:96px;height:96px;border-radius:50%;background:#f3edff;display:flex;align-items:center;justify-content:center}</style>
